CREATE POLICY "cv owner insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'cv' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "cv owner select" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'cv' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "cv owner update" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'cv' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "cv owner delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'cv' AND (storage.foldername(name))[1] = auth.uid()::text);